use hawdb::{Database, Value};
use std::alloc::{GlobalAlloc, Layout, System};
use std::hint::black_box;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::Instant;

struct CountingAllocator;
static CALLS: AtomicU64 = AtomicU64::new(0);
static BYTES: AtomicU64 = AtomicU64::new(0);
unsafe impl GlobalAlloc for CountingAllocator {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        CALLS.fetch_add(1, Ordering::Relaxed);
        BYTES.fetch_add(layout.size() as u64, Ordering::Relaxed);
        unsafe { System.alloc(layout) }
    }
    unsafe fn dealloc(&self, pointer: *mut u8, layout: Layout) {
        unsafe { System.dealloc(pointer, layout) }
    }
    unsafe fn realloc(&self, pointer: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        CALLS.fetch_add(1, Ordering::Relaxed);
        BYTES.fetch_add(size as u64, Ordering::Relaxed);
        unsafe { System.realloc(pointer, layout, size) }
    }
}
#[global_allocator]
static ALLOCATOR: CountingAllocator = CountingAllocator;
const INSERT: &str = "INSERT INTO thread_messages (content_message_id, thread_storage_id, order_index, content, token_count) VALUES ($1, $2, $3, $4, $5)";
fn values(id: usize) -> Vec<Value> {
    vec![Value::String(format!("message-{id:08}")), Value::String(format!("thread-{:04}", id / 128)), Value::Int((id % 128) as i64), Value::String("x".repeat(1024)), Value::Int(256)]
}
fn fixture() -> Database {
    let mut db = Database::new();
    db.query_sql("CREATE TABLE thread_messages (content_message_id TEXT PRIMARY KEY, thread_storage_id TEXT NOT NULL, order_index BIGINT NOT NULL, content TEXT NOT NULL, token_count BIGINT NOT NULL)").unwrap();
    db.query_sql("CREATE INDEX idx_thread_messages_order ON thread_messages (thread_storage_id, order_index, content_message_id)").unwrap();
    for thread in 0..128 {
        let mut tx = db.begin_transaction();
        for message in 0..128 {
            tx.query_sql_with_params(INSERT, &values(thread * 128 + message)).unwrap();
        }
        tx.commit().unwrap();
    }
    db
}
fn measure(round: usize, label: &str, count: usize, mut action: impl FnMut(usize)) {
    CALLS.store(0, Ordering::Relaxed);
    BYTES.store(0, Ordering::Relaxed);
    let start = Instant::now();
    for i in 0..count { action(i); }
    let elapsed = start.elapsed().as_nanos();
    let calls = CALLS.load(Ordering::Relaxed);
    let bytes = BYTES.load(Ordering::Relaxed);
    println!("{round},{label},{count},{elapsed},{calls},{bytes}");
}
fn main() {
    println!("round,case,count,elapsed_ns,allocation_calls,allocated_bytes");
    for round in 0..3 {
        for offset in 0..3 {
            let mode = (round + offset) % 3;
            let mut db = fixture();
            if mode == 0 {
                measure(round, "direct_snapshot", 4096, |_| { black_box(db.begin_read_transaction()); });
                measure(round, "direct_write", 512, |i| { db.query_sql_with_params(INSERT, &values(16384 + i)).unwrap(); });
                assert_eq!(db.query_sql("SELECT count(*) AS n FROM thread_messages").unwrap().rows[0]["n"], Value::Int(16896));
            } else if mode == 1 {
                let mut snapshot = db.begin_read_transaction();
                measure(round, "standing_snapshot_write", 512, |i| {
                    db.query_sql_with_params(INSERT, &values(16384 + i)).unwrap();
                    snapshot = db.begin_read_transaction();
                });
                assert_eq!(snapshot.query_sql("SELECT count(*) AS n FROM thread_messages").unwrap().rows[0]["n"], Value::Int(16896));
            } else {
                let concurrent = db.into_concurrent();
                measure(round, "published_snapshot", 4096, |_| { black_box(concurrent.begin_read_transaction().unwrap()); });
                const POINT: &str = "SELECT content_message_id, thread_storage_id, order_index, content, token_count FROM thread_messages WHERE content_message_id = $1";
                const PAGE: &str = "SELECT content_message_id, thread_storage_id, order_index, content, token_count FROM thread_messages WHERE thread_storage_id = $1 ORDER BY order_index, content_message_id LIMIT $2";
                let point = vec![Value::String("message-00000000".into())];
                let page = vec![Value::String("thread-0000".into()), Value::Int(32)];
                let expected_ids = (0..32).map(|i| Value::String(format!("message-{i:08}"))).collect::<Vec<_>>();
                let expected_thread = Value::String("thread-0000".into());
                let expected_content = Value::String("x".repeat(1024));
                let check = |output: hawdb::QueryOutput, count: usize| {
                    assert_eq!(output.rows.len(), count);
                    for (i, row) in output.rows.iter().enumerate() {
                        assert_eq!(row["content_message_id"], expected_ids[i]);
                        assert_eq!(row["thread_storage_id"], expected_thread);
                        assert_eq!(row["order_index"], Value::Int(i as i64));
                        assert_eq!(row["content"], expected_content);
                        assert_eq!(row["token_count"], Value::Int(256));
                    }
                };
                check(concurrent.query_sql_with_params(POINT, &point).unwrap(), 1);
                check(concurrent.query_sql_with_params(PAGE, &page).unwrap(), 32);
                measure(round, "published_point", 4096, |_| {
                    check(concurrent.query_sql_with_params(POINT, &point).unwrap(), 1);
                });
                measure(round, "published_page", 1024, |_| {
                    check(concurrent.query_sql_with_params(PAGE, &page).unwrap(), 32);
                });
                measure(round, "concurrent_write", 512, |i| { concurrent.query_sql_with_params(INSERT, &values(16384 + i)).unwrap(); });
                assert_eq!(concurrent.query_sql("SELECT count(*) AS n FROM thread_messages").unwrap().rows[0]["n"], Value::Int(16896));
            }
        }
    }
}

