use hawdb::{ConcurrentDatabase, Database, Value};
use std::path::PathBuf;
use std::sync::{Arc, Barrier};
use std::time::{Duration, Instant};
const INSERT: &str = "INSERT INTO thread_messages (content_message_id, thread_storage_id, order_index, content, token_count) VALUES ($1, $2, $3, $4, $5)";
const POINT: &str = "SELECT content_message_id, thread_storage_id, order_index, content, token_count FROM thread_messages WHERE content_message_id = $1";
fn main() {
 let root=PathBuf::from(std::env::args().nth(1).unwrap());
 std::fs::create_dir_all(&root).unwrap();let path=root.join("database");
 let mut db=Database::open(&path).unwrap();
 db.query_sql("CREATE TABLE thread_messages (content_message_id TEXT PRIMARY KEY, thread_storage_id TEXT NOT NULL, order_index BIGINT NOT NULL, content TEXT NOT NULL, token_count BIGINT NOT NULL)").unwrap();
 db.query_sql("CREATE INDEX idx_thread_messages_order ON thread_messages (thread_storage_id, order_index, content_message_id)").unwrap();
 for thread in 0..128 {let mut tx=db.begin_transaction();for message in 0..128 {
  tx.query_sql_with_params(INSERT,&[Value::String(format!("message-{thread:04}-{message:04}")),Value::String(format!("thread-{thread:04}")),Value::Int(message),Value::String("x".repeat(1024)),Value::Int(256)]).unwrap();
 }tx.commit().unwrap();}db.checkpoint().unwrap();drop(db);
 let db=ConcurrentDatabase::open(&path).unwrap();
 let check=|output:hawdb::QueryOutput,thread:usize,message:usize|{
  assert_eq!(output.rows.len(),1);let row=&output.rows[0];assert_eq!(row.len(),5);
  assert_eq!(row["content_message_id"],Value::String(format!("message-{thread:04}-{message:04}")));
  assert_eq!(row["thread_storage_id"],Value::String(format!("thread-{thread:04}")));
  assert_eq!(row["order_index"],Value::Int(message as i64));
  assert_eq!(row["content"],Value::String("x".repeat(1024)));assert_eq!(row["token_count"],Value::Int(256));
 };
 for worker in 0..4 {for request in 0..128 {let thread=(worker*17+request*13)%128;let message=(worker*11+request*7)%128;
  check(db.query_sql_with_params(POINT,&[Value::String(format!("message-{thread:04}-{message:04}"))]).unwrap(),thread,message);
 }}
 std::fs::write(root.join("ready"),b"ready").unwrap();
 while !root.join("start").exists(){std::thread::sleep(Duration::from_millis(1));}
 let barrier=Arc::new(Barrier::new(5));let started=Instant::now();
 let samples=std::thread::scope(|scope|{let mut handles=Vec::new();for worker in 0..4 {
  let db=db.clone();let barrier=Arc::clone(&barrier);let check=&check;
  handles.push(scope.spawn(move||{let mut elapsed=Vec::with_capacity(65536);barrier.wait();for request in 0..65536 {
   let thread=(worker*17+request*13)%128;let message=(worker*11+request*7)%128;
   let params=[Value::String(format!("message-{thread:04}-{message:04}"))];let start=Instant::now();
   let output=db.query_sql_with_params(POINT,&params).unwrap();elapsed.push(start.elapsed().as_nanos() as u64);check(output,thread,message);
  }elapsed}));}barrier.wait();handles.into_iter().flat_map(|h|h.join().unwrap()).collect::<Vec<_>>()});
 let phase=started.elapsed();assert_eq!(samples.len(),262144);let mut samples=samples;samples.sort_unstable();
 println!("requests={},phase_ns={},p50_ns={},p95_ns={},p99_ns={}",samples.len(),phase.as_nanos(),samples[samples.len()/2],samples[(samples.len()*95).div_ceil(100)-1],samples[(samples.len()*99).div_ceil(100)-1]);
 drop(db);let mut db=Database::open(&path).unwrap();assert_eq!(db.query_sql("SELECT count(*) AS n FROM thread_messages").unwrap().rows[0]["n"],Value::Int(16384));drop(db);
 std::fs::remove_dir_all(path).unwrap();
}
